let nextId = 100, toastTimer, dragId = null;
const projectById = id => projects.find(p=>p.id===id);
const hostById = id => hosts.find(h=>h.id===id);
const nodeById = id => state.nodes.find(n=>n.id===id);
const children = (parent,nodes=state.nodes) => nodes.filter(n=>n.parent===parent).sort((a,b)=>a.order-b.order);
const app = document.querySelector('#app');
const overlay = document.querySelector('#overlay');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function snapshot(){return structuredClone({nodes:state.nodes,tabs:state.tabs,favorites:state.favorites,memories:state.memories});}
function mutate(label,fn){state.history.push({label,data:snapshot()});if(state.history.length>30)state.history.shift();fn();state.version++;closeMenu();render();toast(label+' · 可撤销');}
function undo(){const entry=state.history.pop();if(!entry)return toast('还没有需要撤销的操作');Object.assign(state,entry.data);if(!state.tabs.some(t=>t.id===state.tab))state.tab='favorites';state.version++;render();toast('已撤销：'+entry.label);}
function isDescendant(candidate,id){let node=nodeById(candidate);const seen=new Set();while(node){if(node.id===id)return true;if(seen.has(node.id))return true;seen.add(node.id);node=nodeById(node.parent);}return false;}
function canMove(id,parent){const n=nodeById(id),p=nodeById(parent);return !!n && !isDescendant(parent,id) && (parent===null||p?.kind==='category'||(p?.kind==='project'&&n.kind==='workspace'));}
function moveNode(id,parent,before){if(!canMove(id,parent))return toast('这个位置不能接收该节点');mutate('已移动节点',()=>{const n=nodeById(id);n.parent=parent;const siblings=children(parent).filter(x=>x.id!==id);const index=before?siblings.findIndex(x=>x.id===before):-1;siblings.splice(index<0?siblings.length:index,0,n);siblings.forEach((x,i)=>x.order=i);if(parent)state.collapsed.delete(parent);});}
function sortNode(id,dir){const node=nodeById(id);if(!node)return;const siblings=children(node.parent),idx=siblings.indexOf(node);let next=dir==='top'?0:dir==='bottom'?siblings.length-1:idx+(dir==='up'?-1:1);next=Math.max(0,Math.min(next,siblings.length-1));if(next===idx)return toast('已经在边界位置');mutate('已调整排序',()=>{siblings.splice(idx,1);siblings.splice(next,0,node);siblings.forEach((x,i)=>x.order=i);});}
function button(action,text,iconName,attrs='',className='btn'){return `<button class="${className}" data-action="${action}" ${attrs}>${iconName?icon(iconName):''}${text}</button>`;}
function iconButton(action,name,label,attrs=''){return `<button class="icon-btn" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${icon(name)}</button>`;}
function nativeNodes(){return projects.flatMap((p,i)=>[{id:'native-'+p.id,kind:'project',name:p.name,project:p.id,parent:null,order:i},...p.instances.map((h,j)=>({id:'native-'+p.id+'-'+h,kind:'workspace',name:hostById(h).name,project:p.id,host:h,parent:'native-'+p.id,order:j}))]);}
function treeRows(parent=null,depth=0,nodes=state.nodes){return children(parent,nodes).map(n=>{
  if(n.hidden&&!state.showHidden)return '';
  if(n.flat&&!state.showHidden)return treeRows(n.id,depth,nodes);
  const kids=children(n.id,nodes),closed=state.collapsed.has(n.id),host=n.host?hostById(n.host):null;
  return `<div class="tree-row ${n.hidden?'hidden-node':''}" style="--depth:${Math.min(depth,7)}" data-node="${esc(n.id)}" ${state.mode==='custom'?'draggable="true"':''}>
    ${kids.length?`<button class="icon-btn" style="width:15px;height:24px" data-action="collapse" data-id="${esc(n.id)}" aria-label="${closed?'展开':'收起'} ${esc(n.name)}">${icon(closed?'right':'down','chevron')}</button>`:'<span style="width:15px;flex-shrink:0"></span>'}
    ${icon(n.kind==='category'?'folder':n.kind==='workspace'?'branch':'project','tree-icon')}
    <button class="tree-label" data-action="node-open" data-id="${esc(n.id)}" title="${esc(n.name)}">${esc(n.name)}${n.flat?' <span class="source-tag">已合并层级</span>':''}</button>
    ${host?`<span class="dot host-dot ${host.online?'':'off'}" title="${esc(host.name)}"></span>`:''}
    ${state.mode==='custom'?`<button class="icon-btn row-menu" data-action="node-menu" data-id="${esc(n.id)}" aria-label="操作 ${esc(n.name)}">${icon('more')}</button>`:''}
  </div>${!closed?treeRows(n.id,depth+1,nodes):''}`;
}).join('');}
